/* generated child CSS: 07-comparison/comparison.two-col-seo-matrix/block.css */
/* lab-ui block · comparison.two-col-seo-matrix
   Depends: 00-tokens/tokens.css. Light theme. */

.seo-compare {
  --seo-compare-shell-radius: clamp(1.25rem, 3.125vw, 2.5rem);
  position: relative;
  padding-top: 6.25rem;
  padding-bottom: 6.25rem;
  overflow: hidden;
  isolation: isolate;
  border-radius: var(--seo-compare-shell-radius);
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}

.seo-compare::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 58%;
  border-radius: var(--seo-compare-shell-radius);
  background:
    radial-gradient(
      62% 48% at 52% 66%,
      rgba(102, 202, 232, 0.34) 0%,
      rgba(102, 202, 232, 0.18) 34%,
      rgba(102, 202, 232, 0) 72%
    ),
    radial-gradient(
      48% 42% at 36% 72%,
      rgba(229, 118, 111, 0.28) 0%,
      rgba(229, 118, 111, 0.12) 42%,
      rgba(229, 118, 111, 0) 74%
    ),
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0) 0%,
      #dde2ea 18%,
      #8e97a9 39%,
      #353c4d 64%,
      #111827 100%
    );
  clip-path: polygon(
    0 0,
    8% 2%,
    18% 6%,
    30% 12%,
    42% 18%,
    50% 21%,
    58% 18%,
    70% 12%,
    82% 6%,
    92% 2%,
    100% 0,
    100% 100%,
    0 100%
  );
  pointer-events: none;
  z-index: 0;
}

.seo-compare .container {
  position: relative;
  z-index: 1;
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.seo-compare-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.seo-compare-eyebrow {
  margin: 0 0 1.25rem;
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  letter-spacing: var(--type-eyebrow-tracking);
  text-transform: uppercase;
  background: var(
    --cta-secondary-fill,
    linear-gradient(90deg, #56422d 0%, #494938 100%)
  );
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
}

.seo-compare-title {
  margin: 0;
  color: var(--color-heading);
  font-size: var(--type-h2-size);
  font-weight: var(--type-h2-weight);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.seo-compare-title-logo {
  display: inline-block;
  width: 22.885625rem;
  height: 3.348125rem;
  flex-shrink: 0;
  vertical-align: middle;
  margin-top: -0.625rem;
}

.seo-compare-lede {
  margin: 1.5rem 0 0;
  font-size: var(--type-lead-size);
  font-weight: var(--type-lead-weight);
  line-height: var(--type-lead-leading);
  color: var(--color-text);
  max-width: 56rem;
  text-wrap: pretty;
}

.seo-compare-card {
  position: relative;
  width: 100%;
  margin-top: 3.75rem;
  padding: 1rem;
  background-color: var(--color-light-card-bg);
  border-radius: var(--radius-card);
  backdrop-filter: blur(var(--backdrop-blur-table));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-table));
}

.seo-compare-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--radius-card);
  padding: 0.125rem;
  background: var(--color-light-gray-stroke);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  z-index: 1;
}

.seo-compare-grid {
  position: relative;
  display: grid;
  grid-template-columns: 28% 36% 36%;
}

.seo-compare-head,
.seo-compare-row {
  display: contents;
}

.seo-compare-sw-frame {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 28%;
  right: auto;
  width: 36%;
  background: var(--color-white);
  border-radius: 0.875rem;
  box-shadow: 0 0 40.8px 0 #ccdfff;
  pointer-events: none;
}

[dir="rtl"] .seo-compare-sw-frame {
  left: auto;
  right: 28%;
}

.seo-compare-sw-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1.5px;
  background: linear-gradient(180deg, #6bc0f9 0%, #dbeeff 100%);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.seo-compare-grid > * > * {
  position: relative;
  z-index: 2;
}

.seo-compare-brand,
.seo-compare-head-spacer {
  padding: 1.875rem 1.75rem 1.5rem;
}

.seo-compare-brand h3 {
  margin: 0;
  color: var(--color-heading);
  font-size: var(--type-h3-size);
  font-weight: var(--type-h3-weight);
  line-height: var(--type-h3-leading);
  letter-spacing: var(--type-h3-tracking);
  text-align: center;
  text-wrap: balance;
}

.seo-compare-brand--sw h3 :is(strong, b) {
  font-weight: var(--type-h3-weight);
}

.seo-compare-brand p {
  margin: 0.75rem 0 0;
  font-size: 0.9375rem;
  line-height: 1.55;
  color: var(--color-gray-second);
  text-wrap: pretty;
}

.seo-compare-row h4 {
  margin: 0;
  font-size: clamp(1rem, 1.03vw, 1.1875rem);
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.02em;
  color: var(--color-heading);
  padding: 1.5rem 1.25rem 1.5rem 1.5rem;
  /* Stretch to the full grid-row height (so the border-top separator
     lines up with the value cells) and center the text inside. */
  display: flex;
  align-items: center;
  text-wrap: balance;
}

.seo-compare-value {
  padding: 1.5rem 1.75rem;
}

.seo-compare-row h4,
.seo-compare-value {
  border-top: 1px solid rgba(27, 29, 37, 0.06);
}

.seo-compare-row:first-of-type h4,
.seo-compare-row:first-of-type .seo-compare-value {
  border-top: none;
}

.seo-compare-value-label {
  display: none;
}

.seo-compare-value-body {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.seo-compare-value-body p {
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.6;
  text-wrap: pretty;
}

.seo-compare-icon-source {
  display: none;
}

.seo-compare-value--sw .seo-compare-value-body p {
  color: #343a49;
}

.seo-compare-value--competitor .seo-compare-value-body p {
  color: #343a49;
}

/* Shared status icons — same drawing as comparison.three-col-with-mobile-cards:
   19px circle, status tokens, white CSS-drawn check. */
.seo-compare-icon {
  width: 19px;
  height: 19px;
  flex: 0 0 19px;
  position: relative;
  border-radius: 999px;
  margin-top: 0.0625rem;
}

.seo-compare-status--check .seo-compare-icon,
.seo-compare-status--yes .seo-compare-icon {
  background: var(--color-status-yes, #76d98f);
}

.seo-compare-status--neutral .seo-compare-icon,
.seo-compare-status--partial .seo-compare-icon {
  background: var(--color-status-partial, #d7d9dc);
}

.seo-compare-status--cross .seo-compare-icon,
.seo-compare-status--no .seo-compare-icon {
  background: var(--color-status-no, #ff6b6b);
}

.seo-compare-status--check .seo-compare-icon::before,
.seo-compare-status--yes .seo-compare-icon::before,
.seo-compare-status--neutral .seo-compare-icon::before,
.seo-compare-status--partial .seo-compare-icon::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 8px;
  height: 4px;
  border-left: 2px solid #f9f9f9;
  border-bottom: 2px solid #f9f9f9;
  border-radius: 1px;
  transform: rotate(-45deg);
}

.seo-compare-status--cross .seo-compare-icon::before,
.seo-compare-status--cross .seo-compare-icon::after,
.seo-compare-status--no .seo-compare-icon::before,
.seo-compare-status--no .seo-compare-icon::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8.5px;
  width: 9px;
  height: 2px;
  border-radius: 999px;
  background: #f9f9f9;
}

.seo-compare-status--cross .seo-compare-icon::before,
.seo-compare-status--no .seo-compare-icon::before {
  transform: rotate(45deg);
}

.seo-compare-status--cross .seo-compare-icon::after,
.seo-compare-status--no .seo-compare-icon::after {
  transform: rotate(-45deg);
}

.seo-compare-status--none .seo-compare-icon {
  display: none;
}

@media (max-width: 63.999rem) {
  .seo-compare {
    padding-top: 3.75rem;
    padding-bottom: 3.75rem;
  }

  .seo-compare-title {
    gap: 0.5rem;
  }

  .seo-compare-title-logo {
    width: 11.25rem;
    height: 1.625rem;
    margin-top: -0.25rem;
  }

  .seo-compare-eyebrow {
    margin-bottom: 0.9375rem;
  }

  .seo-compare-lede {
    margin-top: 0.9375rem;
  }

  .seo-compare-card {
    margin-top: 1.875rem;
    padding: 0.75rem;
  }

  .seo-compare-grid {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
  }

  .seo-compare-sw-frame {
    display: none;
  }

  .seo-compare-head {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
  }

  .seo-compare-head-spacer {
    display: none;
  }

  .seo-compare-brand {
    border-radius: 0.875rem;
    padding: 1.25rem;
    background: var(--color-white);
    border: 1px solid #e0e8f4;
  }

  .seo-compare-brand--sw {
    border: 1.5px solid #a9d6f9;
    box-shadow: 0 0 30px 0 #ccdfff;
  }

  .seo-compare-brand p {
    font-size: 0.875rem;
  }

  .seo-compare-row {
    display: block;
    border-radius: 0.875rem;
    padding: 1.25rem;
    background: var(--color-white);
    border: 1px solid #e0e8f4;
  }

  .seo-compare-row h4 {
    padding: 0;
    font-size: 1.05rem;
    border-top: none;
  }

  .seo-compare-value {
    padding: 0;
    margin-top: 1rem;
    border-top: none;
  }

  .seo-compare-value-label {
    display: block;
    margin: 0 0 0.5rem;
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1.2;
    text-transform: uppercase;
  }

  .seo-compare-value--sw .seo-compare-value-label {
    color: #4f95ff;
  }

  .seo-compare-value--competitor .seo-compare-value-label {
    color: var(--color-gray-blue);
  }

  .seo-compare-value-body {
    gap: 0.625rem;
  }

  .seo-compare-value-body p {
    font-size: 0.875rem;
  }
}

javascript:
/* generated child JS: 07-comparison/comparison.two-col-seo-matrix/block.js */
// lab-ui block · comparison.two-col-seo-matrix
// Applies CMS-authored status icon values.

(() => {
  const ready = (fn) => {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else fn();
  };

  ready(() => {
    document
      .querySelectorAll('[data-block="comparison.two-col-seo-matrix"]')
      .forEach((section) => {
        section.querySelectorAll(".seo-compare-value-body").forEach((valueBody) => {
          const rawIcon = valueBody.querySelector(".seo-compare-icon-source")?.textContent?.trim();
          const icon = /^(check|yes|neutral|partial|cross|no|none)$/.test(rawIcon || "")
            ? rawIcon
            : "neutral";
          valueBody.classList.add("seo-compare-status--" + icon);
        });
      });
  });
})();
